#pragma once
// Folder-backed optical layout: a small metadata file + ordinary extracted payload files.
// No disc image is opened or reconstructed. Generated by layout.py.
#include <algorithm>
#include <cstdint>
#include <cstring>
#include <filesystem>
#include <fstream>
#include <limits>
#include <sstream>
#include <string>
#include <vector>

namespace port_install {
class ExtractedDisc {
    struct Extent { uint64_t start, size, offset; std::filesystem::path path; };
    std::filesystem::path root_;
    std::vector<Extent> extents_;
    uint64_t bytes_ = 0;
public:
    uint64_t size() const { return bytes_; }
    bool open(const std::filesystem::path& root) {
        if (root == root_ && bytes_) return true;
        root_ = root; bytes_ = 0; extents_.clear();
        std::ifstream input(root / ".disc/layout.tsv");
        std::string line;
        if (!std::getline(input, line)) return false;
        std::istringstream header(line);
        std::string magic;
        uint64_t total = 0;
        if (!(header >> magic >> total) || magic != "EXTRACTED_DISC_V1" || !total) return false;
        uint64_t end = 0;
        while (std::getline(input, line)) {
            std::istringstream row(line);
            Extent e{};
            if (!(row >> e.start >> e.size >> e.offset) || row.get() != '\t') return false;
            std::string name;
            std::getline(row, name);
            if (!name.empty() && name.back() == '\r') name.pop_back();
            std::filesystem::path relative = std::filesystem::u8path(name);
            if (name.empty() || relative.is_absolute() || relative.has_root_name() || name.find('\\') != std::string::npos || name.find(':') != std::string::npos) return false;
            for (const auto& part : relative) if (part == ".." || part == ".") return false;
            if (e.start < end || e.start > total || e.size > total - e.start) return false;
            e.path = root / relative;
            end = e.start + e.size;
            extents_.push_back(e);
            if (extents_.size() > 200000) return false;
        }
        if (extents_.empty()) return false;
        bytes_ = total;
        return true;
    }
    bool fileLbn(const std::filesystem::path& file, uint32_t& lbn) const {
        for (const auto& e : extents_) {
            if (e.offset == 0 && e.path.lexically_normal() == file.lexically_normal()) {
                lbn = static_cast<uint32_t>(e.start / 2048u); return true;
            }
        }
        return false;
    }
    bool read(uint64_t offset, void* destination, size_t count) const {
        if ((!destination && count) || offset > bytes_ || count > bytes_ - offset) return false;
        auto* out = static_cast<uint8_t*>(destination);
        std::memset(out, 0, count);
        const uint64_t end = offset + count;
        for (const auto& e : extents_) {
            if (e.start >= end) break;
            if (e.start + e.size <= offset) continue;
            const uint64_t begin = std::max(offset, e.start);
            const uint64_t wanted = std::min(end, e.start + e.size) - begin;
            std::ifstream file(e.path, std::ios::binary | std::ios::ate);
            if (!file) return false;
            const auto fileEnd = file.tellg();
            if (fileEnd < 0) return false;
            const uint64_t size = static_cast<uint64_t>(fileEnd);
            const uint64_t position = e.offset + begin - e.start;
            if (position >= size) {
                if (position - size >= 2048u) return false;
                continue; // only the final sector's padding is zero-filled
            }
            const uint64_t actual = std::min(wanted, size - position);
            if (wanted - actual >= 2048u) return false;
            file.seekg(static_cast<std::streamoff>(position));
            file.read(reinterpret_cast<char*>(out + begin - offset), static_cast<std::streamsize>(actual));
            if (static_cast<uint64_t>(file.gcount()) != actual) return false;
        }
        return true;
    }
};
} // namespace port_install
